#!/usr/bin/env bash
# Covers verify_apks.sh. auto-release.yml only runs on a tag push, so without
# this a regression would not surface until a release was already being cut.
#
# An APK is a zip, so the fixtures are built with python's zipfile and need no
# Android toolchain. Every negative case asserts the message as well as the
# exit status: a script that merely exits non-zero for the wrong reason - or
# dies on a syntax error - would otherwise satisfy almost the whole suite.
set -Eeuo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SCRIPT="$HERE/verify_apks.sh"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
failures=0

pass() { printf '  ok    %s\n' "$1"; }
fail() {
  printf '  FAIL  %s\n' "$1"
  [[ -n "${2:-}" ]] && printf '%s\n' "$2" | sed 's/^/          /'
  failures=$((failures + 1))
}

run() { bash "$SCRIPT" "$@" 2>&1; }

# accepts <label> <dir>
accepts() {
  local out
  if out="$(run "$2")"; then pass "$1"; else fail "$1" "$out"; fi
}

# refuses <label> <dir> <expected message substring>
refuses() {
  local out
  if out="$(run "$2")"; then
    fail "$1 (was accepted)" "$out"
  elif [[ "$out" != *"$3"* ]]; then
    fail "$1 (refused for the wrong reason; wanted \"$3\")" "$out"
  else
    pass "$1"
  fi
}

# A snapshot large enough to clear the script's floor.
SNAPSHOT_BYTES=$((1024 * 1024 + 32))

# Every `.so` in a fixture has to be a readable ELF, because the alignment
# check reads program headers: a run of zero bytes is reported as "not an ELF"
# and every case here would then be refused for a reason it is not about.
# `elfmk.for_abi` writes them and owns what a real library in a given
# `lib/<abi>/` looks like - a copy of that rule here is the bug its docstring
# records.
#
# `elf_page_align_test.sh` drives the parser through the same helper, one case
# per malformed shape, which is where those belong: each shell case here costs
# a whole four-artifact `dist/`. What this file covers is the wiring - that
# `verify_apks.sh` passes the ABIs an artifact's name implies, turns findings
# into faults, and keeps "found something" apart from "could not run".
export PYTHONPATH="$HERE"

# What the Sentry Gradle plugin writes, copied from a real release APK.
SENTRY_PROPS='# Generated by sentry-android-gradle-plugin
io.sentry.ProguardUuids=1d0c7dd0-d7e4-3ad8-9c9f-9c6f0c75a5b1
io.sentry.build-tool=gradle
'

# apk <path> <abi>...   (QU_SO_ALIGN overrides the p_align every .so asks for)
apk() {
  python3 - "$SNAPSHOT_BYTES" "$SENTRY_PROPS" "$@" <<'PY'
import os, sys, zipfile, elfmk
size, props, path, abis = int(sys.argv[1]), sys.argv[2], sys.argv[3], sys.argv[4:]
align = int(os.environ.get("QU_SO_ALIGN", "16384"))
with zipfile.ZipFile(path, "w") as z:
    z.writestr("AndroidManifest.xml", "manifest")
    z.writestr("classes.dex", "dex")
    z.writestr("classes2.dex", "dex")          # real APKs have these; must not confuse the check
    z.writestr("resources.arsc", "res")
    z.writestr("assets/flutter_assets/lib/fonts/x.ttf", "font")
    z.writestr("assets/sentry-debug-meta.properties", props)
    for abi in abis:
        z.writestr(f"lib/{abi}/libapp.so", elfmk.for_abi(abi, size=size, aligns=(align,)))
        z.writestr(f"lib/{abi}/libflutter.so", elfmk.for_abi(abi, size=4096, aligns=(align,)))
        z.writestr(f"lib/{abi}/libapp.so.sym", "symbols")  # superstring; pins the exact-line match
PY
}

# aab <path> <abi>...   (QU_SO_ALIGN applies here too)
#
# The same contents one level in, under the base module, which is where a real
# App Bundle puts them. `BundleConfig.pb` and `base/resources.pb` are not
# checked by anything; they are here so the fixture is the shape a reader
# recognises rather than the subset the gate happens to look at.
aab() {
  python3 - "$SNAPSHOT_BYTES" "$SENTRY_PROPS" "$@" <<'PY'
import os, sys, zipfile, elfmk
size, props, path, abis = int(sys.argv[1]), sys.argv[2], sys.argv[3], sys.argv[4:]
align = int(os.environ.get("QU_SO_ALIGN", "16384"))
uuid_props = os.environ.get("QU_AAB_SENTRY_PROPS", props)
with zipfile.ZipFile(path, "w") as z:
    z.writestr("BundleConfig.pb", "config")
    z.writestr("base/manifest/AndroidManifest.xml", "manifest")
    z.writestr("base/dex/classes.dex", "dex")
    z.writestr("base/resources.pb", "res")
    z.writestr("base/assets/sentry-debug-meta.properties", uuid_props)
    for abi in abis:
        z.writestr(f"base/lib/{abi}/libapp.so", elfmk.for_abi(abi, size=size, aligns=(align,)))
        z.writestr(f"base/lib/{abi}/libflutter.so", elfmk.for_abi(abi, size=4096, aligns=(align,)))
PY
}

# aab_omitting <path> <entry-to-omit> <abi>...
aab_omitting() {
  python3 - "$SNAPSHOT_BYTES" "$SENTRY_PROPS" "$@" <<'PY'
import os, sys, zipfile, elfmk
size, props, path, omit, abis = int(sys.argv[1]), sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5:]
align = int(os.environ.get("QU_SO_ALIGN", "16384"))
with zipfile.ZipFile(path, "w") as z:
    for entry, body in (
        ("BundleConfig.pb", "config"),
        ("base/manifest/AndroidManifest.xml", "manifest"),
        ("base/dex/classes.dex", "dex"),
        ("base/assets/sentry-debug-meta.properties", props),
    ):
        if not entry.startswith(omit):
            z.writestr(entry, body)
    for abi in abis:
        if not f"base/lib/{abi}/libapp.so".startswith(omit):
            z.writestr(f"base/lib/{abi}/libapp.so", elfmk.for_abi(abi, size=size, aligns=(align,)))
        if not f"base/lib/{abi}/libflutter.so".startswith(omit):
            z.writestr(f"base/lib/{abi}/libflutter.so", elfmk.for_abi(abi, size=4096, aligns=(align,)))
PY
}

# apk_omitting <path> <prefix-to-omit> <abi>...  (prefix drops a file or a whole tree)
apk_omitting() {
  python3 - "$SNAPSHOT_BYTES" "$SENTRY_PROPS" "$@" <<'PY'
import os, sys, zipfile, elfmk
size, props, path, omit, abis = int(sys.argv[1]), sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5:]
# QU_SO_ALIGN is read here as well as in `apk`, so a case that exports it and
# builds through this helper cannot silently get the default instead.
align = int(os.environ.get("QU_SO_ALIGN", "16384"))
with zipfile.ZipFile(path, "w") as z:
    for entry in ("AndroidManifest.xml", "classes.dex"):
        if not entry.startswith(omit):
            z.writestr(entry, "body")
    if not "assets/sentry-debug-meta.properties".startswith(omit):
        z.writestr("assets/sentry-debug-meta.properties", props)
    for abi in abis:
        if not f"lib/{abi}/libapp.so".startswith(omit):
            z.writestr(f"lib/{abi}/libapp.so", elfmk.for_abi(abi, size=size, aligns=(align,)))
        # Kept even when libapp.so is omitted, so a substring match would
        # wrongly satisfy the snapshot check. Only a dropped tree removes it.
        if not (omit.endswith("/") and f"lib/{abi}/libapp.so.sym".startswith(omit)):
            z.writestr(f"lib/{abi}/libapp.so.sym", "symbols")
        if not f"lib/{abi}/libflutter.so".startswith(omit):
            z.writestr(f"lib/{abi}/libflutter.so", elfmk.for_abi(abi, size=4096, aligns=(align,)))
PY
}

good_set() {
  local d="$1"; mkdir -p "$d"
  apk "$d/qunleashed_0.13.0_android_universal.apk"   armeabi-v7a arm64-v8a x86_64
  apk "$d/qunleashed_0.13.0_android_armeabi-v7a.apk" armeabi-v7a
  apk "$d/qunleashed_0.13.0_android_arm64-v8a.apk"   arm64-v8a
  apk "$d/qunleashed_0.13.0_android_x86_64.apk"      x86_64
  aab "$d/qunleashed_0.13.0_android.aab"             armeabi-v7a arm64-v8a x86_64
}

echo "verify_apks.sh"

d="$TMP/good"; good_set "$d"
accepts "a complete artifact set passes" "$d"

d="$TMP/no-snapshot"; good_set "$d"
apk_omitting "$d/qunleashed_0.13.0_android_arm64-v8a.apk" "lib/arm64-v8a/libapp.so" arm64-v8a
refuses "a split APK missing libapp.so is refused" "$d" "the Dart snapshot is missing"

# The task stages nothing when the per-ABI directory is absent, so the APK has
# no lib/ tree at all - not merely a missing file.
d="$TMP/no-lib-tree"; good_set "$d"
apk_omitting "$d/qunleashed_0.13.0_android_x86_64.apk" "lib/x86_64/" x86_64
refuses "an APK with no lib/ tree at all is refused" "$d" "the Dart snapshot is missing"

# Present is not populated.
d="$TMP/empty-snapshot"; good_set "$d"
python3 - "$d/qunleashed_0.13.0_android_x86_64.apk" <<'PY'
import sys, zipfile
with zipfile.ZipFile(sys.argv[1], "w") as z:
    z.writestr("AndroidManifest.xml", "manifest")
    z.writestr("classes.dex", "dex")
    z.writestr("lib/x86_64/libapp.so", b"")
PY
refuses "a zero-byte libapp.so is refused" "$d" "expected at least"

# The listing reads only the central directory, so entry data must be checked.
d="$TMP/corrupt-data"; good_set "$d"
python3 - "$d/qunleashed_0.13.0_android_x86_64.apk" <<'PY'
import sys, zipfile, io
path = sys.argv[1]
raw = bytearray(open(path, "rb").read())
end = raw.rfind(b"PK\x01\x02")           # start of the central directory
raw[:end] = b"\0" * end                  # obliterate the entry data, keep the index
open(path, "wb").write(bytes(raw))
PY
refuses "an APK whose data is corrupt but listable is refused" "$d" "failed its integrity check"

d="$TMP/universal-partial"; good_set "$d"
apk "$d/qunleashed_0.13.0_android_universal.apk" armeabi-v7a arm64-v8a
refuses "a universal APK missing an ABI is refused" "$d" "the Dart snapshot is missing"

d="$TMP/unsplit"; good_set "$d"
apk "$d/qunleashed_0.13.0_android_x86_64.apk" armeabi-v7a arm64-v8a x86_64
refuses "a split APK carrying other ABIs is refused" "$d" "carries an unexpected ABI"

# The same fault in the universal APK, which is a different branch of the
# `case` above it: the split artifacts get `want=("$abi")` and the universal
# one `want=("${ANDROID_ABIS[@]}")`, and only the first was covered - so
# loosening the universal branch passed the whole suite.
#
# The shape is the one #361 produced for real. Asking AGP for ABI splits takes
# away the `abiFilters` Flutter sets only when splits are off, and the universal
# APK comes back carrying a third-party dependency's `lib/x86/` with no
# `libflutter.so` and no `libapp.so` beside it - so Play reads the APK as
# supporting x86 and the app dies at launch on one. Hence a bare library and
# deliberately no engine in the fixture.
d="$TMP/universal-stray-abi"; good_set "$d"
python3 - "$d/qunleashed_0.13.0_android_universal.apk" <<'PY'
import sys, zipfile
with zipfile.ZipFile(sys.argv[1], "a") as z:
    z.writestr("lib/x86/libsomedep.so", "a dependency that ships x86")
PY
refuses "a universal APK carrying an ABI with no engine is refused" "$d" "carries an unexpected ABI"

d="$TMP/no-manifest"; good_set "$d"
apk_omitting "$d/qunleashed_0.13.0_android_x86_64.apk" "AndroidManifest.xml" x86_64
refuses "an APK with no AndroidManifest.xml is refused" "$d" "has no AndroidManifest.xml"

d="$TMP/no-dex"; good_set "$d"
apk_omitting "$d/qunleashed_0.13.0_android_universal.apk" "classes.dex" armeabi-v7a arm64-v8a x86_64
refuses "an APK with no classes.dex is refused" "$d" "has no classes.dex"

# The shape #343 shipped: an APK R8 renamed, with nothing naming the mapping
# that undoes it. Nothing about the build is different, which is the point.
d="$TMP/no-sentry-uuid"; good_set "$d"
apk_omitting "$d/qunleashed_0.13.0_android_arm64-v8a.apk" "assets/sentry-debug-meta.properties" arm64-v8a
refuses "an APK with no Sentry UUID asset is refused" "$d" "nothing ties it to an R8 mapping"

# The plugin writes this file for any feature it has on, so its presence is not
# the mapping's presence.
d="$TMP/empty-sentry-uuid"; good_set "$d"
(
  SENTRY_PROPS='io.sentry.build-tool=gradle
'
  apk "$d/qunleashed_0.13.0_android_x86_64.apk" x86_64
)
refuses "a Sentry UUID asset with no UUID in it is refused" "$d" "with no io.sentry.ProguardUuids in it"

# The key being present is not the value being usable, which is the half a
# loosened pattern would stop checking. `ProguardUuids` is plural and the SDK
# reads it as a list, so a pair is the realistic malformed value: both readers
# here assume one, and that assumption has to be refused rather than silently
# truncated to the first.
d="$TMP/two-sentry-uuids"; good_set "$d"
(
  SENTRY_PROPS='io.sentry.ProguardUuids=1d0c7dd0-d7e4-3ad8-9c9f-9c6f0c75a5b1,2d0c7dd0-d7e4-3ad8-9c9f-9c6f0c75a5b2
'
  apk "$d/qunleashed_0.13.0_android_x86_64.apk" x86_64
)
refuses "two UUIDs in one asset are refused" "$d" "with no io.sentry.ProguardUuids in it"

d="$TMP/malformed-sentry-uuid"; good_set "$d"
(
  SENTRY_PROPS='io.sentry.ProguardUuids=not-a-uuid
'
  apk "$d/qunleashed_0.13.0_android_x86_64.apk" x86_64
)
refuses "a malformed UUID is refused" "$d" "with no io.sentry.ProguardUuids in it"

# Only one mapping is uploaded, so one UUID has to cover every artifact. One
# R8 run makes that so (#361); this is what would notice the two-build shape
# coming back, or a stale APK from an earlier local build being copied in
# beside freshly built ones.
d="$TMP/split-uuid"; good_set "$d"
(
  SENTRY_PROPS='# Generated by sentry-android-gradle-plugin
io.sentry.ProguardUuids=99999999-9999-3999-9999-999999999999
io.sentry.build-tool=gradle
'
  apk "$d/qunleashed_0.13.0_android_x86_64.apk" x86_64
)
refuses "artifacts carrying two different mapping UUIDs are refused" "$d" "different R8 mapping UUIDs"

d="$TMP/unreadable"; good_set "$d"
printf 'not a zip\n' > "$d/qunleashed_0.13.0_android_x86_64.apk"
refuses "an unreadable APK is refused" "$d" "failed its integrity check"

# 16 KB pages, the wiring only; the parser's own shapes are
# `elf_page_align_test.sh`. A library linked with a 4 KB max-page-size
# installs, passes every other check here, and dies at `dlopen` on a device
# running 16 KB pages - at launch, when it is libapp.so.
d="$TMP/align-4k"; good_set "$d"
(
  export QU_SO_ALIGN=4096
  apk "$d/qunleashed_0.13.0_android_arm64-v8a.apk" arm64-v8a
)
refuses "a 4 KB-aligned arm64 split is refused" "$d" "will not load on a 16 KB page device"

# The universal APK is packed separately from the splits, which is the whole
# reason this check runs per artifact - and nothing covered that half.
# Measured: skipping the alignment check for `*universal*` left the suite
# green, while skipping it for the splits was killed three times over. That is
# the same asymmetry the stray-ABI comment further down records for the other
# branch of the same `case`, and #361 is what it cost.
d="$TMP/align-4k-universal"; good_set "$d"
(
  export QU_SO_ALIGN=4096
  apk "$d/qunleashed_0.13.0_android_universal.apk" armeabi-v7a arm64-v8a x86_64
)
refuses "a 4 KB-aligned universal APK is refused" "$d" "will not load on a 16 KB page device"

# 32-bit ABIs are not judged on alignment, because no 16 KB page device can
# run them. The fixture is a real ELFCLASS32 object, which is the half that
# was missing - see `elfmk.py`.
d="$TMP/align-4k-32bit"; good_set "$d"
(
  export QU_SO_ALIGN=4096
  apk "$d/qunleashed_0.13.0_android_armeabi-v7a.apk" armeabi-v7a
)
accepts "a 4 KB-aligned 32-bit split passes" "$d"

# "The check could not run" must not read as a pass, and nothing reached that
# branch before: the one unreadable-APK fixture dies at `unzip -tqq` and never
# gets as far as the helper. Measured - replacing the `if !` with `|| true`
# left the whole suite green. A python3 that is not there is both the cheapest
# way in and a realistic one.
mkdir -p "$TMP/nopy"
printf '#!/bin/sh\nexit 127\n' > "$TMP/nopy/python3"
chmod +x "$TMP/nopy/python3"
d="$TMP/no-python"; good_set "$d"
out="$( (export PATH="$TMP/nopy:$PATH"; run "$d") || true )"
if [[ "$out" == *"could not be checked for 16 KB page alignment"* ]]; then
  pass "a check that cannot run is refused, not passed"
else
  fail "a check that cannot run is refused, not passed" "$out"
fi

# A zero exit with something on stderr is a third outcome, and folding the two
# streams together - which `2>&1` did - made it the worst one: the first
# `DeprecationWarning` from a newer runner image would have been reported as a
# library that will not load. `PYTHONVERBOSE=1` stands in for it, and did
# exactly that when measured.
d="$TMP/noisy-check"; good_set "$d"
out="$( (export PYTHONVERBOSE=1; run "$d") || true )"
if [[ "$out" == *"exited 0 but wrote to stderr"* ]]; then
  pass "a check that writes to stderr is not read as a pass"
else
  fail "a check that writes to stderr is not read as a pass" "$out"
fi

# --- the App Bundle ---------------------------------------------------------
#
# Play does not accept an APK for a new application, so the bundle is the
# artifact a submission uploads and the one every store user installs. The
# parser's shapes are `elf_page_align_test.sh`; what these cover is that this
# script looks in the right places inside a bundle, and that the bundle is
# held to the same guarantees as the APKs.

d="$TMP/no-bundle"; good_set "$d"
rm -f "$d/qunleashed_0.13.0_android.aab"
refuses "an artifact set with no App Bundle is refused" "$d" "No App Bundle"

d="$TMP/bundle-no-dex"; good_set "$d"
aab_omitting "$d/qunleashed_0.13.0_android.aab" "base/dex/classes.dex" armeabi-v7a arm64-v8a x86_64
refuses "a bundle with no base/dex/classes.dex is refused" "$d" "has no base/dex/classes.dex"

d="$TMP/bundle-no-manifest"; good_set "$d"
aab_omitting "$d/qunleashed_0.13.0_android.aab" "base/manifest/AndroidManifest.xml" armeabi-v7a arm64-v8a x86_64
refuses "a bundle with no base manifest is refused" "$d" "has no base/manifest/AndroidManifest.xml"

d="$TMP/bundle-no-snapshot"; good_set "$d"
aab_omitting "$d/qunleashed_0.13.0_android.aab" "base/lib/arm64-v8a/libapp.so" armeabi-v7a arm64-v8a x86_64
refuses "a bundle missing a Dart snapshot is refused" "$d" "has no base/lib/arm64-v8a/libapp.so"

# The alignment check has to reach `base/lib/`, one level deeper than an APK's.
d="$TMP/bundle-align"; good_set "$d"
(
  export QU_SO_ALIGN=4096
  aab "$d/qunleashed_0.13.0_android.aab" armeabi-v7a arm64-v8a x86_64
)
refuses "a 4 KB-aligned library inside the bundle is refused" "$d" "will not load on a 16 KB page device"

# A bundle's UUID may differ from the APKs', and that is the design rather
# than a defect: AGP refuses a bundle while ABI splits are on, so the bundle
# comes from its own Gradle invocation, its own R8 run and therefore its own
# mapping. `upload_r8_mapping.sh` sends both, each under the UUID of the
# artifact it describes. Asserted as an `accepts`, because the obvious reading
# of #361 is that two UUIDs are always a bug, and this is the one place that
# says where the line is.
d="$TMP/bundle-own-uuid"; good_set "$d"
(
  export QU_AAB_SENTRY_PROPS='# Generated by sentry-android-gradle-plugin
io.sentry.ProguardUuids=99999999-9999-3999-9999-999999999999
io.sentry.build-tool=gradle
'
  aab "$d/qunleashed_0.13.0_android.aab" armeabi-v7a arm64-v8a x86_64
)
accepts "a bundle carrying its own mapping UUID is accepted" "$d"

# What is not allowed is a bundle with no UUID to file a mapping under. It is
# the worst shape available here, because the bundle is what Play installs, so
# the half that would not deobfuscate is every store user's.
d="$TMP/bundle-blank-uuid"; good_set "$d"
(
  export QU_AAB_SENTRY_PROPS='io.sentry.build-tool=gradle
'
  aab "$d/qunleashed_0.13.0_android.aab" armeabi-v7a arm64-v8a x86_64
)
refuses "a bundle with no usable mapping UUID is refused" "$d" "with no io.sentry.ProguardUuids in it"

# The missing-asset shape for a bundle, which the "no separate UUID assertion"
# reasoning in `verify_apks.sh` depends on: without this case a mutation that
# removed the per-artifact fault would survive, and the argument would rest on
# a gap in this suite rather than on the code.
d="$TMP/bundle-no-sentry"; good_set "$d"
aab_omitting "$d/qunleashed_0.13.0_android.aab" "base/assets/sentry-debug-meta.properties" armeabi-v7a arm64-v8a x86_64
refuses "a bundle with no Sentry UUID asset is refused" "$d" "nothing ties it to an R8 mapping"

# A bundle whose entry data is corrupt but listable. Both pre-existing
# integrity cases use an APK, so the bundle branch of that check was uncovered.
d="$TMP/bundle-corrupt"; good_set "$d"
python3 - "$d/qunleashed_0.13.0_android.aab" <<'PY2'
import sys
path = sys.argv[1]
raw = bytearray(open(path, "rb").read())
end = raw.rfind(b"PK")
raw[:end] = b"␀" * end
open(path, "wb").write(bytes(raw))
PY2
refuses "a bundle whose data is corrupt but listable is refused" "$d" "failed its integrity check"

# A 32-bit library inside the bundle has to be inspected, not skipped. Nothing
# pinned that: restricting the parser's bundle shape to 64-bit ABIs survived
# the whole suite, because the "nothing inspected" guard only covers 64-bit
# ABIs - so a stub where a 32-bit library should be went unreported.
d="$TMP/bundle-32bit-stub"; good_set "$d"
python3 - "$d/qunleashed_0.13.0_android.aab" <<'PY2'
import sys, zipfile
with zipfile.ZipFile(sys.argv[1], "a") as z:
    z.writestr("base/lib/armeabi-v7a/libstub.so", "a stub where a library should be")
PY2
refuses "a stub .so under the bundle's 32-bit ABI is refused" "$d" "not an ELF file"

# Nothing clears `dist/`, so a leftover from another version survives a local
# re-run - and `upload_r8_mapping.sh` would read its UUID off whichever sorted
# first, which for a version number is the older one.
d="$TMP/two-bundles"; good_set "$d"
cp "$d/qunleashed_0.13.0_android.aab" "$d/qunleashed_0.12.0_android.aab"
refuses "two App Bundles in one directory are refused" "$d" "a release produces exactly one"

d="$TMP/two-universal"; good_set "$d"
cp "$d/qunleashed_0.13.0_android_universal.apk" "$d/qunleashed_0.12.0_android_universal.apk"
refuses "two universal APKs in one directory are refused" "$d" "a release produces exactly one"

d="$TMP/stray"; good_set "$d"
apk "$d/qunleashed_0.13.0_android_riscv64.apk" riscv64
refuses "an artifact with an unrecognised name is refused" "$d" "does not match any known"

# The build guards this too, but this is the gate that must not trust the build.
d="$TMP/partial-set"; mkdir -p "$d"
apk "$d/qunleashed_0.13.0_android_universal.apk" armeabi-v7a arm64-v8a x86_64
refuses "an incomplete artifact set is refused" "$d" "No armeabi-v7a APK"

d="$TMP/no-universal"; mkdir -p "$d"
apk "$d/qunleashed_0.13.0_android_armeabi-v7a.apk" armeabi-v7a
apk "$d/qunleashed_0.13.0_android_arm64-v8a.apk"   arm64-v8a
apk "$d/qunleashed_0.13.0_android_x86_64.apk"      x86_64
refuses "a set with no universal APK is refused" "$d" "No universal APK"

d="$TMP/empty"; mkdir -p "$d"
refuses "a directory with no artifacts is refused" "$d" "No Android artifacts found"
refuses "a missing directory is refused" "$TMP/does-not-exist" "No Android artifacts found"

# One run must report every problem, not stop at the first.
d="$TMP/many"; good_set "$d"
apk_omitting "$d/qunleashed_0.13.0_android_x86_64.apk" "classes.dex" x86_64
apk_omitting "$d/qunleashed_0.13.0_android_arm64-v8a.apk" "lib/arm64-v8a/libapp.so" arm64-v8a
out="$(run "$d" || true)"
if [[ "$out" == *"has no classes.dex"* && "$out" == *"the Dart snapshot is missing"* ]]; then
  pass "one run reports every broken artifact"
else
  fail "one run reports every broken artifact" "$out"
fi

# A rejected artifact must not also be logged as ok.
if [[ "$out" == *"  ok  qunleashed_0.13.0_android_x86_64.apk"* ]]; then
  fail "a failing APK is still logged as ok" "$out"
else
  pass "a failing APK is not logged as ok"
fi

if (( failures )); then
  echo "$failures failure(s)" >&2
  exit 1
fi
echo "all passed"
